use lean_runtime::semantics::sint;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(
            acc,
            sint::int8_dec_lt((x >> 56) as u8, (x >> 48) as u8) as u64,
        );
    }
    acc
}

fn main() {
    run(|| (), kernel)
}
